def _redact_secrets_pem(text: str) -> tuple[str, bool]:
    """Apply PEM swallowing; return (text, saw_unterminated)."""
    lines = _split_on_newline_only(text)
    if not lines and text:
        lines = [text]
    out: list[str] = []
